function callAwardReleasePreviewMatches(preview,identity){if(!preview||preview.period_kind!==identity.p_period_kind||!/^\d{4}-\d{2}-\d{2}$/.test(preview.period_start||'')||!/^\d{4}-\d{2}-\d{2}$/.test(preview.period_end||'')||preview.period_start>=preview.period_end)return false;if(identity.p_period_kind==='season')return Number(preview.season)===Number(identity.p_season);return !identity.p_period_date||(identity.p_period_date>=preview.period_start&&identity.p_period_date<preview.period_end);}
