function callAwardReleaseAction(kind,update=false,meta=null){const range=callAwardReleaseRange(meta),noun=meta&&Array.isArray(meta.awards)&&!meta.awards.length?'results':'awards';return range?`${update?'Update':'Release'} ${noun} for ${range}`:kind==='season'?'Release season awards':'Release selected awards';}
function callAwardReleaseTimestamp(value,data){return value?(typeof callDateTime==='function'?callDateTime(value,data.settings?.timezone):String(value)):'';}
function renderCallAwardReleasePreview(preview){if(!preview)return '';const awards=Array.isArray(preview.awards)?preview.awards:[];return `<div class="call-release-preview"><h3 id="callAwardReleasePreviewHeading" tabindex="-1">${esc(callAwardReleaseLabel(preview.period_kind))} · ${esc(callAwardReleaseRange(preview))}</h3><p class="help">Check the winners, prizes and claim conditions below. Batting and prediction awards use the recorded result date within this period. Engagement uses the activity week. Play from the current period is separate. Weekly or four-week release also reveals the included player predictions, club estimates and named peer predictions; season release does not.</p>${awards.length?`<div class="call-release-awards">${awards.map(award=>{const prize=String(award.reward_text||'').trim(),name=award.label||(typeof callAwardLabel==='function'?callAwardLabel(award.key,award.cadence||preview.period_kind):String(award.key||'Award').replaceAll('_',' '));return `<article><h4>${esc(name)}</h4>${(award.winners||[]).length?award.winners.map(winner=>`<p><strong>${esc(winner.name||'Club member')}</strong>${winner.detail?`<br><span class="help">${esc(winner.detail)}</span>`:''}</p>`).join(''):'<p class="help">No qualifying winner yet.</p>'}<p><strong>${prize?'Club prize:':'Recognition only'}</strong>${prize?' '+esc(prize):''}</p>${prize&&award.claim_text?`<p class="help"><strong>To claim:</strong> ${esc(award.claim_text)}</p>`:''}</article>`;}).join('')}</div>`:'<p class="help">No awards are selected for this period. Any included predictions and confirmed scores can still be released.</p>'}</div>`;}
