 return `<details class="call-score-entry" id="callScore-${esc(id)}" data-call-score="${esc(id)}" ${ensureMakeYourCallState().scoreId===id?'open':''}><summary><span><strong>${esc(c.name)}</strong><small>${esc(formatDateShort(c.match_date))} · ${esc(c.opposition||'')} · ${esc(formatLabel(c.format_key))}</small></span><span>${official?.status==='pending'?'Record score':esc(callResultText(official))}</span></summary>${form}</details>`;
