 return `<section class="card call-scoring"><div class="call-board-heading"><h2>Official scores <span class="call-board-range">${esc(callBoardWeekRange(data,{compact:true}))}</span></h2>${renderCallWeekPicker(data)}</div>${entries.map(renderCallScoreEntry).join('')||'<p class="help">No scores to record for this week.</p>'}</section>`;
