function renderCallSettings(data){
 if(!data.can_manage)return '';const s=data.settings||{},state=ensureMakeYourCallState(),editing=state.editSettings,staff=(data.members||[]).filter(m=>['captain','coach','head_coach','admin','lead_admin'].includes(m.permission_role));let suggested='Australia/Sydney';try{suggested=Intl.DateTimeFormat().resolvedOptions().timeZone||suggested;}catch{}
 return `<section class="card call-settings" id="callSettingsEditor" ${editing?'':'hidden'}><h2>Club setup</h2><form data-call-form="settings" id="callSettingsForm"><p class="help">Tick the awards your club wants to include. Set a prize, collection condition and frequency where needed, then save once.</p><label class="call-check"><input type="checkbox" id="callEnabled" ${s.enabled?'checked':''}> Enable Make your prediction</label><label class="call-check"><input type="checkbox" id="callConversationEnabled" ${s.conversation_enabled===true?'checked':''}> Include Club Conversation</label><label for="callTimezone">Club timezone</label><input id="callTimezone" value="${esc(s.timezone||suggested)}" placeholder="Australia/Sydney" required><p class="help">Entries and votes close at midnight at the start of the nominated match date. Existing published deadlines stay fixed.</p><div class="call-settings-grid"><div><label for="callWeekStartDay">Our award week starts on</label><select id="callWeekStartDay">${CALL_WEEK_DAYS.map((day,i)=>`<option value="${i}" ${Number(s.week_start_day??1)===i?'selected':''}>${day}</option>`).join('')}</select></div><div><label for="callSeasonMonth">Season starts</label><select id="callSeasonMonth">${Array.from({length:12},(_,i)=>`<option value="${i+1}" ${(s.season_start_month||7)===i+1?'selected':''}>${new Intl.DateTimeFormat('en',{month:'long',timeZone:'UTC'}).format(new Date(Date.UTC(2020,i,1)))}</option>`).join('')}</select></div></div><p class="help" id="callScheduleHelp">${esc(s.schedule_help||'Prize and frequency changes update current and future periods. Closed periods keep their saved prizes.')}${s.week_start_effective?` Weekday changes take effect ${esc(formatDateShort(s.week_start_effective))}; existing weeks stay intact.`:''}</p><label for="callSeasonAwardsVisibility">Season standings</label><select id="callSeasonAwardsVisibility"><option value="live" ${s.season_awards_visibility!=='on_release'?'selected':''}>Live — show current leaders</option><option value="on_release" ${s.season_awards_visibility==='on_release'?'selected':''}>Hold until released</option></select><p class="help">Weekly and four-week awards wait for your club to release them.</p><h3>Awards</h3><p class="help">Unticked awards stay out of the current page and future announcements.</p><div class="call-settings-grid">${CALL_AWARD_KEYS.map(key=>renderCallAwardSetting(key,s)).join('')}</div><div id="callFourWeekSettings"><label for="callFourWeekStart">First four-week award period starts</label><input type="date" id="callFourWeekStart" value="${esc(s.award_cycle_start||data.release_defaults?.weekly?.period_end||data.week_start||'')}"><p class="help">Choose the first award week. Awards then cover four club weeks at a time.</p></div><div class="btnrow"><button type="submit" class="btn" id="callSaveSettings">Save club setup</button><button type="button" class="btn ghost" id="callCancelSettings">Close editor</button></div><p class="status" data-call-status role="status"></p></form><details class="call-result-permissions"><summary>Result permissions</summary><p class="help">Tick everyone who should record official results, then save once. Captains, Coaches and Head Coaches also need existing edit access to each player. Club Admin access is included.</p><form data-call-form="grants" id="callGrantsForm">${staff.map(m=>`<label class="call-check call-permission-row"><input type="checkbox" id="callGrant-${esc(m.user_id)}" ${m.can_record_results?'checked':''} ${['admin','lead_admin'].includes(m.permission_role)?'disabled':''}><span><strong>${esc(m.name)}</strong><small>${esc(String(m.permission_role).replaceAll('_',' '))}${['admin','lead_admin'].includes(m.permission_role)?' · included':''}</small></span></label>`).join('')||'<p class="help">No eligible staff to grant yet.</p>'}<button class="btn" type="submit" id="callSaveGrants">Saved ✓</button><p class="status" data-call-status role="status"></p></form></details></section>`;}
function syncCallSettingsForms(){for(const key of CALL_AWARD_KEYS){const options=document.getElementById('callAwardOptions-'+key);if(options)options.hidden=!callAwardChoiceChecked(key);}const fourWeek=document.getElementById('callFourWeekSettings');if(fourWeek)fourWeek.hidden=!CALL_RECURRING_AWARDS.some(key=>callAwardChoiceChecked(key)&&document.getElementById('callCadence-'+key)?.value==='monthly');for(const key of CALL_AWARD_KEYS){const reward=document.getElementById('callReward-'+key),condition=document.getElementById('callClaimSetting-'+key);if(reward&&condition)condition.hidden=!reward.value.trim();}for(const [id,buttonId,label]of [['callSettingsForm','callSaveSettings','Save club setup'],['callGrantsForm','callSaveGrants','Save permissions']]){const form=document.getElementById(id),button=document.getElementById(buttonId);if(!form||!button)continue;const pending=makeYourCallCommands.has(form.dataset.callForm),dirty=form.callBaseline!==makeYourCallFormState(form),initial=id==='callSettingsForm'&&!makeYourCallCache?.settings?.timezone;button.disabled=makeYourCallSaving||(!pending&&!dirty&&!initial);button.textContent=pending?'Confirm save':dirty||initial?label:'Saved ✓';button.classList.toggle('secondary',!dirty&&!initial&&!pending);}}
function renderCallGrinch(data){if(!data.settings?.grinch_enabled)return '';const pending=callSeasonVisibility(data).pending,rows=pending?[]:data.grinch_rows||[],best=Math.max(0,...rows.map(r=>Number(r.low_calls)||0)),winners=rows.filter(r=>best>0&&Number(r.low_calls)===best);return `<div class="notice compact call-grinch-award"><h3>${esc(data.settings.grinch_name||'The Grinch')}</h3>${renderCallAwardHelp('grinch','season',data.settings.grinch_name||'The Grinch')}${winners.length?winners.map(r=>`<p><strong>${esc(r.name)}</strong> · ${esc(r.low_calls)} of ${esc(r.comparable_calls)} calls proved too low</p>`).join(''):`<p class="help">${pending?'Results will be announced here.':'No one qualifies yet.'}</p>`}<p class="help">${esc(callRewardText(data.settings.rewards,'grinch'))}</p>${renderCallClaim(data.settings.rewards,'grinch')}</div>`;}
