function renderCallMessages(data){if(data.settings?.conversation_enabled!==true)return '';return `<section class="card call-conversation"><h2>Club Conversation</h2><p class="help">For your club. Back a teammate and keep the banter kind.</p><div class="call-messages">${(data.messages||[]).map(m=>`<article><header class="call-message-heading"><div class="call-message-byline"><strong>${esc(m.name)}</strong><time datetime="${esc(m.created_at)}">${esc(callDateTime(m.created_at,data.settings?.timezone))}</time></div><div class="call-message-actions">${m.can_delete?`<button class="btn ghost" type="button" data-call-delete="${esc(m.id)}">Remove</button>`:''}${m.reported?'<span class="help">Reported to Club Admin</span>':`<button class="btn ghost" type="button" data-call-report="${esc(m.id)}">Report</button>`}</div></header><p class="call-message-body">${esc(m.body)}</p></article>`).join('')||'<p class="help">No messages yet. Start the conversation.</p>'}</div><form data-call-form="message" id="callMessageForm"><label for="callMessage">Your message</label><textarea id="callMessage" maxlength="500" rows="2" placeholder="Back a teammate. Keep the banter kind."></textarea><button class="btn" type="submit">Post to this week</button><p class="status" data-call-status role="status"></p></form>${data.can_manage&&(data.reports||[]).length?`<details><summary>Reported messages (${data.reports.length})</summary>${data.reports.map(r=>`<p><strong>${esc(r.reporter_name)}</strong>: ${esc(r.reason)} <button class="btn ghost" data-call-delete="${esc(r.message_id)}">Remove reported message</button></p>`).join('')}</details>`:''}</section>`;}
