for(const c of data.calls||[]){const slider=document.getElementById('callVoteRange-'+c.id),numeric=document.getElementById('callVote-'+c.id);if(slider&&numeric){const syncSlider=()=>{const value=String(numeric.value).trim(),valid=/^\d+$/.test(value)&&Number(value)<=999;slider.classList.toggle('call-vote-unset',!valid);slider.setAttribute('aria-valuetext',valid?value+' runs':'No prediction selected');if(valid){slider.setAttribute('max',String(callVoteSliderMaximum(value)));slider.value=value;}else slider.value='0';};slider.oninput=()=>{numeric.value=slider.value;syncSlider();};numeric.oninput=syncSlider;syncSlider();}submit('callVoteForm-'+c.id,'save_make_your_call_vote',()=>{if(!callVotingOpen(c))throw new Error('Predictions closed at midnight as this match date began.');return {entry_id:c.id,runs:callNumber(val('callVote-'+c.id),999,'Your prediction'),expected_revision:c.my_vote?.revision||0};},'Saved ✓');submit('callResultForm-'+c.id,'save_make_your_call_result',()=>{const status=val('callResultStatus-'+c.id),reason=val('callCorrection-'+c.id),official=callOfficialResult(c);if(official?.status!=='pending'&&!reason)throw new Error('Add the reason for correcting this result.');return {entry_id:c.id,expected_revision:official?.revision||0,status,score_date:val('callResultDate-'+c.id)||official?.score_date||c.match_date,runs:status==='played'?callNumber(val('callRuns-'+c.id),9999,'Official runs'):null,not_out:status==='played'&&document.getElementById('callNotOut-'+c.id).checked,reason};},'Official result saved. Game totals and the player’s My Innings use this result.');const resultStatus=document.getElementById('callResultStatus-'+c.id);if(resultStatus){const sync=()=>{document.getElementById('callResultForm-'+c.id).querySelector('[data-call-result-runs]').hidden=resultStatus.value!=='played';};resultStatus.onchange=sync;sync();}}
